package secretbunker

import (
	"encoding/hex"
	"reflect"
	"testing"
)

// Golden vectors generated by the Rust implementation's postcard encoder
// (secret-bunker-iroh: proto::tests::wire_format_is_stable). The two test
// suites share these bytes; a mismatch means the wire contract broke.

func TestRequestGoldenVectors(t *testing.T) {
	cases := []struct {
		name string
		got  []byte
		want string
	}{
		{"get", encGet("prod", "db"), "000470726f64026462"},
		{"put", encPut("g", "n", []byte{1, 2, 255}, 300), "010167016e030102ffac02"},
		{"list-groups", encListGroups(), "0a"},
		{"grant", encGrant("g", "id", 7), "08016702696407"},
	}
	for _, c := range cases {
		if got := hex.EncodeToString(c.got); got != c.want {
			t.Errorf("%s: encoded %s, want %s", c.name, got, c.want)
		}
	}
}

func TestResponseGoldenVectors(t *testing.T) {
	cases := []struct {
		name string
		hex  string
		want Response
	}{
		{"denied", "00", Denied{}},
		{"secret", "020268698001", Secret{Value: []byte("hi"), Version: 128}},
		{"names", "0502016101016202", Names{{"a", 1}, {"b", 2}}},
		{
			"groups",
			"070101016705",
			Groups{ServiceAdmin: true, Groups: []GroupInfo{{Name: "g", Perms: 5}}},
		},
		{"failed", "09026e6f", Failed{Reason: "no"}},
		{"conflict", "04ffff03", VersionConflict{Current: 65535}},
	}
	for _, c := range cases {
		buf, err := hex.DecodeString(c.hex)
		if err != nil {
			t.Fatal(err)
		}
		got, err := decodeResponse(buf)
		if err != nil {
			t.Fatalf("%s: decode: %v", c.name, err)
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("%s: decoded %#v, want %#v", c.name, got, c.want)
		}
	}
}

func TestDecodeRejectsMalformedInput(t *testing.T) {
	cases := map[string]string{
		"empty":             "",
		"unknown variant":   "63",
		"truncated string":  "0904",
		"trailing bytes":    "0000",
		"invalid bool":      "0702",
		"truncated varint":  "0402ff",
		"string not utf8":   "0901ff",
		"overlong byte len": "02ff02",
	}
	for name, h := range cases {
		buf, err := hex.DecodeString(h)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := decodeResponse(buf); err == nil {
			t.Errorf("%s (%s): expected decode error, got none", name, h)
		}
	}
}

func TestVarintRoundtrip(t *testing.T) {
	for _, v := range []uint64{0, 1, 127, 128, 300, 65535, 1 << 32, ^uint64(0)} {
		e := &encoder{}
		e.uvarint(v)
		d := &decoder{buf: e.buf}
		got, err := d.uvarint()
		if err != nil || got != v || d.done() != nil {
			t.Errorf("roundtrip %d: got %d, err %v", v, got, err)
		}
	}
}
